 * timestamp, so the two legacy spellings collapse into this one).
 */
function newestRunTime(a, b) {
    return Date.parse((b && (b.updated_at || b.created_at)) || 0) -
           Date.parse((a && (a.updated_at || a.created_at)) || 0);
